function salvar_foto_anuncio($arquivo,&$erros){if(empty($arquivo['name'])){$erros[]='A foto do anúncio é obrigatória.';return '';}$mime=(new finfo(FILEINFO_MIME_TYPE))->file($arquivo['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($ext[$mime])){$erros[]='Envie uma foto JPG, PNG ou WebP.';return '';}$dir=__DIR__.'/../assets/uploads/ads';if(!is_dir($dir))mkdir($dir,0755,true);$nome=bin2hex(random_bytes(16)).'.'.$ext[$mime];if(!move_uploaded_file($arquivo['tmp_name'],$dir.'/'.$nome)){$erros[]='Não foi possível salvar a foto.';return '';}return '/assets/uploads/ads/'.$nome;}
