 if($acao==='criar'){$categoria=normalizar_rotulo($_POST['categoria']??'');$nome=normalizar_rotulo($_POST['nome']??'');$descricao=trim($_POST['descricao']??'');$link=normalizar_url_publicitaria($_POST['link_url']??'');$duracao=(int)($_POST['duracao_segundos']??10);$imagem=salvar_foto_anuncio($_FILES['foto']??[],$erros);if(mb_strlen($categoria)<2)$erros[]='Selecione uma categoria.';if(mb_strlen($nome)<3)$erros[]='Informe o nome do anúncio.';if(mb_strlen($descricao)<10)$erros[]='A descrição deve ter ao menos 10 caracteres.';if($link===false)$erros[]='Informe um domínio válido, como narrativas.site.';if($duracao<5||$duracao>20)$erros[]='O tempo de exposição deve ficar entre 5 e 20 segundos.';if(!$erros){$stmt=$mysqli->prepare("INSERT INTO anuncios_profissionais(profissional_id,categoria,titulo,texto,imagem_url,link_url,duracao_segundos,status) VALUES(?,?,?,?,?,?,?,'aprovado')");$stmt->bind_param('isssssi',$perfil['id'],$categoria,$nome,$descricao,$imagem,$link,$duracao);$stmt->execute();$id_anuncio=$mysqli->insert_id;$codigo='VXAD-'.str_pad((string)$id_anuncio,8,'0',STR_PAD_LEFT);$stmt=$mysqli->prepare('UPDATE anuncios_profissionais SET codigo=? WHERE id=?');$stmt->bind_param('si',$codigo,$id_anuncio);$stmt->execute();mensagem_sucesso('Anúncio publicado gratuitamente. Código: '.$codigo);redirecionar('/dashboard/anuncios.php');}}
